/**
 * Streams the editor-safe bytes of an asset referenced by the exact design-template version that is public right now. Anonymous: no session, cookie or storage credential is involved. The asset id is subordinate and grants nothing on its own — there is no address that serves an asset outside the template and version that authorise it. Publication, the current published version, the version document that references the asset, the durable template association, product and placement eligibility, and the derivative are all re-checked on every request, so unpublishing or archiving the template, publishing a newer version, retiring a side or an area, or withdrawing the product stops delivery immediately even for a caller that already knows the address. Only the current published version is addressable: an older version that was once public is refused exactly as an unknown one is. Responses are never cached.
 * @summary Get one asset placed by the current published version of a design template
 */
export const publicDesignTemplateAssetGet = (
  slug: string,
  version: number,
  assetId: string,
  options?: SecondParameter<typeof apiRequest<Blob>>,
) => {
  return apiRequest<Blob>(
    {
      url: `/api/public/design-templates/${slug}/versions/${version}/assets/${assetId}`,
      method: 'GET',
      responseType: 'blob',
    },
    options,
  );
};

/**
 * Returns what is owed on the deposit of the one order belonging to the custom request the presented secure link grants access to. The request comes from the grant and the order from the request, so there is no order id, obligation id, attempt id, amount or customer identifier in the body. The amount is the DEPOSIT obligation’s own frozen figure — no share of a total is recomputed and no quotation is read — and the currency is the obligation’s own VND. The bank instructions are server-owned configuration, and the transfer reference is derived from the order code, so it is identical on every read. The remaining payment is neither shown nor payable here. Reading writes nothing: no attempt is opened, no state moves and the link is not consumed. Every token that does not open a live grant, and every request with no deposit to read, answer with one identical 404.
 * @summary Read the deposit a secure link opens
 */
export const publicOrderDepositCurrent = (
  readDepositBody: ReadDepositBody,
  options?: SecondParameter<typeof apiRequest<PublicOrderDepositCurrent200>>,
) => {
  return apiRequest<PublicOrderDepositCurrent200>(
    {
      url: `/api/public/orders/deposit`,
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      data: readDepositBody,
    },
    options,
  );
};

/**
 * Records that the customer is about to transfer the deposit. The order, the DEPOSIT obligation, the amount, the currency and the step-up evidence are all resolved by the server from the grant — none of them is accepted from the caller. Inside one transaction the grant is re-checked under its row lock, the obligation must still be awaiting payment, a recent re-verification of the customer’s own contact is required, and one BANK_TRANSFER attempt is created at PENDING for the obligation’s exact amount. This is **not** a payment: no attempt is settled, no obligation is satisfied, no order becomes DEPOSIT_PAID and no reconciliation is written — only an Admin verifying that the money arrived can do any of that. Repeating the call with the same Idempotency-Key replays the same attempt and creates no second one; a deliberate retry sends a new key.
 * @summary Open one bank-transfer attempt against the deposit a secure link opens
 */
export const publicOrderDepositInitiate = (
  initiateDepositAttemptBody: InitiateDepositAttemptBody,
  options?: SecondParameter<typeof apiRequest<PublicOrderDepositInitiate201>>,
) => {
  return apiRequest<PublicOrderDepositInitiate201>(
    {
      url: `/api/public/orders/deposit/attempts`,
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      data: initiateDepositAttemptBody,
    },
    options,
  );
};

/**
 * Streams a single PNG, JPEG or WebP image of at most 10485760 bytes into private storage, records it against the named bank-transfer attempt and queues inspection. Transfer evidence is **optional** and supporting only: it helps the workshop reconcile the payment faster, and a correct transfer with no image at all is verified in exactly the same way. It changes nothing — no attempt is settled, no deposit is satisfied, no order becomes DEPOSIT_PAID and no verification is recorded. The order, the deposit, the customer and the step-up evidence are all resolved by the server from the secure link; the attempt id names which attempt the image belongs to and is proved against that link before a byte is read. Append-only: at most 5 images per attempt, and none can be deleted or replaced. A retry opens a new attempt with an evidence set of its own. Idempotent: repeating the request with the same Idempotency-Key and the same file returns the original result and writes no second image, submission or inspection.
 * @summary Submit one transfer image for one bank-transfer attempt
 */
export const publicOrderDepositEvidenceUpload = (
  publicOrderDepositEvidenceUploadBody: PublicOrderDepositEvidenceUploadBody,
  options?: SecondParameter<typeof apiRequest<PublicOrderDepositEvidenceUpload202>>,
) => {
  const formData = new FormData();
  formData.append(`accessToken`, publicOrderDepositEvidenceUploadBody.accessToken);
  formData.append(`attemptId`, publicOrderDepositEvidenceUploadBody.attemptId);
  formData.append(`file`, publicOrderDepositEvidenceUploadBody.file);

  return apiRequest<PublicOrderDepositEvidenceUpload202>(
    {
      url: `/api/public/orders/deposit/evidence`,
      method: 'POST',
      headers: { 'Content-Type': 'multipart/form-data' },
      data: formData,
    },
    options,
  );
};

/**
 * Lists what has been submitted for the named bank-transfer attempt and how far inspection has got with each, so the payment screen can say "sent" and then "received" truthfully. Answers only for an attempt the presented link opens; anything else is indistinguishable from not existing. Bounded at 5 entries, so there is no pagination, and an empty list is an ordinary case. It reads only: nothing is submitted, no payment, order or asset state changes, and no image content is served — the response carries metadata and status, never bytes, a URL or a storage location.
 * @summary Read the transfer images already submitted for one attempt
 */
export const publicOrderDepositEvidenceStatus = (
  readTransferEvidenceBody: ReadTransferEvidenceBody,
  options?: SecondParameter<typeof apiRequest<PublicOrderDepositEvidenceStatus200>>,
) => {
  return apiRequest<PublicOrderDepositEvidenceStatus200>(
    {
      url: `/api/public/orders/deposit/evidence/status`,
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      data: readTransferEvidenceBody,
    },
    options,
  );
};

/**
 * Streams a PNG QR encoding the bank transfer for this deposit: the merchant’s bank and account, the DEPOSIT obligation’s exact amount and the derived transfer reference. It is an EMVCo/NAPAS account-transfer payload — a banking application reads it and pre-fills the transfer — and it is not a checkout session: it contains no application URL, no secure-link token, no attempt id and no provider reference. The image is generated locally on the server on every request from immutable inputs and is never stored, so no object, asset or storage key exists for it. Requesting it changes no payment state whatsoever. The same 404 as the deposit read answers every unusable token and every order with no deposit.
 * @summary Download the bank-transfer QR for the deposit a secure link opens
 */
export const publicOrderDepositQr = (
  depositQrBody: DepositQrBody,
  options?: SecondParameter<typeof apiRequest<Blob>>,
) => {
  return apiRequest<Blob>(
    {
      url: `/api/public/orders/deposit/qr`,
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      data: depositQrBody,
      responseType: 'blob',
    },
    options,
  );
};

/**
 * Returns what is owed on the remaining balance of the one order belonging to the custom request the presented secure link grants access to. The request comes from the grant and the order from the request, so there is no order id, obligation id, attempt id, amount or customer identifier in the body. The amount is the REMAINING obligation’s own frozen figure, copied from the accepted quotation at order creation — no total minus deposit is recomputed and no quotation is read — and the currency is the obligation’s own VND. The bank instructions are server-owned configuration, and the transfer reference is derived from the order code with the RM suffix, so it is identical on every read and distinct from the deposit memo. The deposit is neither shown nor payable here. This read stays available after the payment window closes, so a customer whose balance an Admin has verified can see that; `payable` is what distinguishes the two. Reading writes nothing: no attempt is opened, no state moves and the link is not consumed. Every token that does not open a live grant, and every request with no live REMAINING obligation, answer with one identical 404.
 * @summary Read the final payment a secure link opens
 */
export const publicOrderFinalPaymentCurrent = (
  readFinalPaymentBody: ReadFinalPaymentBody,
  options?: SecondParameter<typeof apiRequest<PublicOrderFinalPaymentCurrent200>>,
) => {
  return apiRequest<PublicOrderFinalPaymentCurrent200>(
    {
      url: `/api/public/orders/final-payment`,
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      data: readFinalPaymentBody,
    },
    options,
  );
};

/**
 * Records that the customer is about to transfer the remaining balance. The order, the REMAINING obligation, the amount, the currency and the step-up evidence are all resolved by the server from the grant — none of them is accepted from the caller, and the DEPOSIT obligation cannot be reached through this route. Inside one transaction the grant is re-checked under its row lock, the order must be AWAITING_FINAL_PAYMENT and the obligation still PENDING, a recent re-verification of the customer’s own contact is required, and one BANK_TRANSFER attempt is created at PENDING for the obligation’s exact amount. This is **not** a payment: no attempt is settled, no obligation is satisfied, no order becomes READY_FOR_DELIVERY and no reconciliation is written — only an Admin verifying that the money arrived can do any of that. Repeating the call with the same Idempotency-Key replays the same attempt and creates no second one; a deliberate retry sends a new key.
 * @summary Open one bank-transfer attempt against the final payment a secure link opens
 */
export const publicOrderFinalPaymentInitiate = (
  initiateFinalPaymentAttemptBody: InitiateFinalPaymentAttemptBody,
  options?: SecondParameter<typeof apiRequest<PublicOrderFinalPaymentInitiate201>>,
) => {
  return apiRequest<PublicOrderFinalPaymentInitiate201>(
    {
      url: `/api/public/orders/final-payment/attempts`,
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      data: initiateFinalPaymentAttemptBody,
    },
    options,
  );
};

/**
 * Streams a PNG QR encoding the bank transfer for the remaining balance: the merchant’s bank and account, the REMAINING obligation’s exact amount and the derived RM transfer reference. It is an EMVCo/NAPAS account-transfer payload — a banking application reads it and pre-fills the transfer — and it is not a checkout session: it contains no application URL, no secure-link token, no attempt id and no provider reference. The image is generated locally on the server on every request from immutable inputs and is never stored, so no object, asset or storage key exists for it. Requesting it changes no payment state whatsoever. Unlike the read, it is refused unless the balance is currently payable, because a QR is an instruction to send money and one served outside that window would invite a transfer nobody owes. The same 404 as the final-payment read answers every unusable token and every order with no live REMAINING obligation.
 * @summary Download the bank-transfer QR for the final payment a secure link opens
 */
export const publicOrderFinalPaymentQr = (
  finalPaymentQrBody: FinalPaymentQrBody,
  options?: SecondParameter<typeof apiRequest<Blob>>,
) => {
  return apiRequest<Blob>(
    {
      url: `/api/public/orders/final-payment/qr`,
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      data: finalPaymentQrBody,
      responseType: 'blob',
    },
    options,
  );
};

/**
 * Records the customer’s decision to accept a specific higher shipping fee. The order, the customer, the fee currently in force, the currency, the grant and the step-up evidence are all resolved by the server from the secure link — only the new fee being accepted is taken from the caller. Inside one transaction the grant is re-checked under its row lock, the shipping detail is locked and must still be editable, the fee must be a genuine increase over the one the order carries, and a recent re-verification of the customer’s own contact is required. Exactly one immutable acknowledgement is appended. This changes nothing else: the shipping fee is not updated, the remaining balance is not recalculated, no payment is created and the order does not move — the operator applies the fee afterwards, and can only apply the exact increase acknowledged here. Repeating the same confirmation replays it and writes no second record.
 * @summary Accept one exact shipping-fee increase on the order a secure link opens
 */
export const publicOrderShippingFeeAcknowledge = (
  acknowledgeShippingFeeBody: AcknowledgeShippingFeeBody,
  options?: SecondParameter<typeof apiRequest<PublicOrderShippingFeeAcknowledge201>>,
) => {
  return apiRequest<PublicOrderShippingFeeAcknowledge201>(
    {
      url: `/api/public/orders/shipping-fee-acknowledgements`,
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      data: acknowledgeShippingFeeBody,
    },
    options,
  );
};

/**
 * Returns published products in editorial order, page by page. Anonymous: no session or cookie is involved, and the caller cannot select lifecycle visibility — there is no parameter for it, and drafts and archived products are excluded by the query itself. Pagination is keyset: `nextCursor` is opaque, bound to the filter it was issued under, and null on the last page. Responses are never stored. Publication is re-read on every request, and there is no cache-invalidation consumer in this system, so a stored copy could keep an unpublished product visible.
 * @summary List published products
 */
export const publicProductList = (
  params?: PublicProductListParams,
  options?: SecondParameter<typeof apiRequest<PublicProductList200>>,
) => {
  return apiRequest<PublicProductList200>(
    { url: `/api/public/products`, method: 'GET', params },
    options,
  );
};

/**
 * Resolves a published product by its immutable server-owned slug. An unknown slug, a draft, an archived product and a product without a public category all return the same 404: a public caller must not be able to tell unreleased work from work that never existed. Responses are never stored. Publication is re-read on every request, and there is no cache-invalidation consumer in this system, so a stored copy could keep an unpublished product visible.
 * @summary Get one published product by slug
 */
export const publicProductDetail = (
  slug: unknown,
  options?: SecondParameter<typeof apiRequest<PublicProductDetail200>>,
) => {
  return apiRequest<PublicProductDetail200>(
    { url: `/api/public/products/${slug}`, method: 'GET' },
    options,
  );
};

/**
 * Streams the requested rendition of one image attached to a PUBLISHED product. Anonymous: no session, cookie or storage credential is involved. Publication is re-checked on every request, so unpublishing a product stops delivery immediately even for a caller that already knows the address. Responses are never cached.
 * @summary Get one published product image
 */
export const publicProductMediaGet = (
  slug: unknown,
  productMediaId: unknown,
  rendition: 'thumbnail' | 'catalog-preview',
  options?: SecondParameter<typeof apiRequest<Blob>>,
) => {
  return apiRequest<Blob>(
    {
      url: `/api/public/products/${slug}/media/${productMediaId}/${rendition}`,
      method: 'GET',
      responseType: 'blob',
    },
    options,
  );
};

/**
 * The read-only placement a Studio session starts from: active Product Sides and Embroidery Areas of a publicly visible Product, ordered by displayOrder, code and id. Retired rows are absent, and so is every private fact — no background Asset id, storage key, original or derivative URL, inspection detail or mutation field. `studioEligible` is true only when one active side has at least one active area and an approved editor-safe background; incomplete or unprocessed placement reports false rather than inventing geometry. A Product with no placement is still published and still returns a manifest, with an empty side list.
 * @summary Get the public placement manifest
 */
export const publicProductPlacementGet = (
  slug: unknown,
  options?: SecondParameter<typeof apiRequest<PublicProductPlacementGet200>>,
) => {
  return apiRequest<PublicProductPlacementGet200>(
    { url: `/api/public/products/${slug}/placement`, method: 'GET' },
    options,
  );
};

/**
 * Streams the approved editor-safe background of one active Product Side of a PUBLISHED product. Anonymous: no session, cookie or storage credential is involved. Publication, category visibility, side activity, the background association and the derivative are re-checked on every request, so unpublishing a product, retiring a side or replacing a background stops delivery immediately even for a caller that already knows the address. Responses are never cached.
 * @summary Get one published product side background
 */
export const publicProductSideBackgroundGet = (
  slug: unknown,
  sideCode: unknown,
  options?: SecondParameter<typeof apiRequest<Blob>>,
) => {
  return apiRequest<Blob>(
    {
      url: `/api/public/products/${slug}/sides/${sideCode}/background`,
      method: 'GET',
      responseType: 'blob',
    },
    options,
  );
};

/**
 * The variants a customer may choose when creating a catalog custom request, with the product id to submit alongside one. Anonymous: no session or cookie is involved, and there is no parameter of any kind — the caller cannot select lifecycle visibility, and delisted variants are excluded by the query itself. Ordered by the product’s own display order then id, so repeated reads agree. An unknown slug, a draft, an archived product and a product without a public category all return the same 404. A published product with no selectable variant returns an empty list rather than a 404: it exists, it simply cannot form a catalog request. Selection only — no SKU, price, stock or inventory is published here, and no variant is marked as a default. Responses are never stored, because publication is re-read on every request and nothing in this system invalidates a cache.
 * @summary List the selectable variants of a published product
 */
export const publicProductVariantList = (
  slug: unknown,
  options?: SecondParameter<typeof apiRequest<PublicProductVariantList200>>,
) => {
  return apiRequest<PublicProductVariantList200>(
    { url: `/api/public/products/${slug}/variants`, method: 'GET' },
    options,
  );
};

/**
 * Accepts the quotation version the customer was looking at, identified by the `versionId` the current-quotation read returned. The custom request is identified by the grant and never by the caller. Inside one transaction the grant is re-checked under its row lock, a recent re-verification of the customer’s own contact is required, the version must still be the current sent one and still inside its validity window, the acceptance evidence is written, and the custom request moves to QUOTE_ACCEPTED as a system projection. A newer sent version makes an older acceptance fail rather than silently accept the new price. Accepting twice replays the first acceptance and writes nothing. No order, payment or reservation is created.
 * @summary Accept the exact quotation version shown by a secure link
 */
export const publicQuotationAccept = (
  acceptQuotationBody: AcceptQuotationBody,
  options?: SecondParameter<typeof apiRequest<PublicQuotationAccept200>>,
) => {
  return apiRequest<PublicQuotationAccept200>(
    {
      url: `/api/public/quotations/accept`,
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      data: acceptQuotationBody,
    },
    options,
  );
};

/**
 * Returns the quotation version that is current for the one custom request the presented secure link grants access to. The request is identified by the grant, and the version by the request’s and the quotation’s own current pointers — never by the caller: there is no quotation id, version id, request id or customer identifier in the body. A newer sent version makes a later call return that newer version; a superseded one is never served as current. A quotation whose validity has lapsed is still returned in full, flagged `expired`, and is not written to. Every token that does not open a live grant, and every request with no current quotation, answer with one identical 404.
 * @summary Read the quotation a secure link opens
 */
export const publicQuotationCurrent = (
  readCurrentQuotationBody: ReadCurrentQuotationBody,
  options?: SecondParameter<typeof apiRequest<PublicQuotationCurrent200>>,
) => {
  return apiRequest<PublicQuotationCurrent200>(
    {
      url: `/api/public/quotations/current`,
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      data: readCurrentQuotationBody,
    },
    options,
  );
};

/**
 * Declines the quotation version the customer was looking at. Takes the same two fields as acceptance and requires no re-verification, because declining an offer commits nothing. The version must still be the current sent one; a superseded, already decided or never-sent version is refused and the live offer is left untouched. This moves the quotation only: the custom request is **not** rejected and stays in the quotation stage, where the workshop can send a revised version.
 * @summary Decline the exact quotation version shown by a secure link
 */
export const publicQuotationReject = (
  rejectQuotationBody: RejectQuotationBody,
  options?: SecondParameter<typeof apiRequest<PublicQuotationReject200>>,
) => {
  return apiRequest<PublicQuotationReject200>(
    {
      url: `/api/public/quotations/reject`,
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      data: rejectQuotationBody,
    },
    options,
  );
};

/**
 * Exchanges the opaque token from a secure link for the request it grants access to. The token travels in the request body only — never in a path, query or header — so it never reaches a server or proxy access log, and it is never echoed back. Resolving a link does not consume it: the same link works until it expires or is revoked. Every token that does not open a live grant — unknown, expired, revoked, superseded, or issued for something else — answers with one identical 404, so the response reveals nothing about whether a token ever existed.
 * @summary Resolve a secure-link token
 */
export const publicSecureLinkResolve = (
  resolveSecureLinkBody: ResolveSecureLinkBody,
  options?: SecondParameter<typeof apiRequest<PublicSecureLinkResolve200>>,
) => {
  return apiRequest<PublicSecureLinkResolve200>(
    {
      url: `/api/public/secure-links/resolve`,
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      data: resolveSecureLinkBody,
    },
    options,
  );
};

/**
 * Opens a one-time code challenge for a destination and purpose, and hands the code to asynchronous delivery. While a challenge is still live the same one is returned unchanged — use the resend operation to replace it. The response never contains the code, and is identical whether or not the destination already belongs to a customer.
 * @summary Request a verification code for a contact
 */
export const publicVerificationIssue = (
  issueVerificationChallengeBody: IssueVerificationChallengeBody,
  options?: SecondParameter<typeof apiRequest<PublicVerificationIssue202>>,
) => {
  return apiRequest<PublicVerificationIssue202>(
    {
      url: `/api/public/verification/challenges`,
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      data: issueVerificationChallengeBody,
    },
    options,
  );
};

/**
 * Reports the lifecycle state and the expiry of one challenge, and nothing else — no contact, no purpose, no customer and no attempt history. A challenge whose expiry has passed reads EXPIRED whether or not a sweep has run. This operation writes nothing.
 * @summary Read the state of a verification challenge
 */
export const publicVerificationReadStatus = (
  challengeId: string,
  options?: SecondParameter<typeof apiRequest<PublicVerificationReadStatus200>>,
) => {
  return apiRequest<PublicVerificationReadStatus200>(
    { url: `/api/public/verification/challenges/${challengeId}`, method: 'GET' },
    options,
  );
};

/**
 * Submits the six-digit code for a live challenge. A correct code consumes the challenge exactly once and, for a SUBMISSION challenge, establishes the verified customer identity in the same transaction. The response never contains the code, the digest, the contact or the customer, and the challenge cannot be answered again.
 * @summary Answer a verification challenge
 */
export const publicVerificationSubmitAttempt = (
  challengeId: string,
  submitVerificationAttemptBody: SubmitVerificationAttemptBody,
  options?: SecondParameter<typeof apiRequest<PublicVerificationSubmitAttempt200>>,
) => {
  return apiRequest<PublicVerificationSubmitAttempt200>(
    {
      url: `/api/public/verification/challenges/${challengeId}/attempts`,
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      data: submitVerificationAttemptBody,
    },
    options,
  );
};

/**
 * Replaces a live challenge with a new one carrying a new code, after the configured cooldown. The destination and purpose come from the challenge being replaced, so the request carries no body. This is a business reissue, not a delivery retry.
 * @summary Reissue a verification code
 */
export const publicVerificationResend = (
  challengeId: string,
  options?: SecondParameter<typeof apiRequest<PublicVerificationResend202>>,
) => {
  return apiRequest<PublicVerificationResend202>(
    { url: `/api/public/verification/challenges/${challengeId}/resend`, method: 'POST' },
    options,
  );
};

/**
 * Returns the minimum safe identity for the authenticated admin: id, email and display name. No credential, session or role data is exposed.
 * @summary Get the current staff identity
 */
export const staffSelfGet = (options?: SecondParameter<typeof apiRequest<StaffSelfGet200>>) => {
  return apiRequest<StaffSelfGet200>({ url: `/api/staff/me`, method: 'GET' }, options);
};

/**
 * Revokes the current server-side session and clears the cookie.
 * @summary Close the current staff session
 */
export const staffSessionDelete = (options?: SecondParameter<typeof apiRequest<void>>) => {
  return apiRequest<void>({ url: `/api/staff/session`, method: 'DELETE' }, options);
};

/**
 * Authenticates the admin by email and password and sets an HttpOnly, SameSite=Strict session cookie. The session token is never returned in the body.
 * @summary Open a staff session
 */
export const staffSessionCreate = (
  staffLoginRequest: StaffLoginRequest,
  options?: SecondParameter<typeof apiRequest<void>>,
) => {
  return apiRequest<void>(
    {
      url: `/api/staff/session`,
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      data: staffLoginRequest,
    },
    options,
  );
};

